def _get_defer_select_mask(self, opts, mask, select_mask=None):
    if select_mask is None:
        select_mask = {}
    select_mask[opts.pk] = {}

    for field in opts.concrete_fields:
        field_mask = mask.pop(field.name, None)
        field_att_mask = mask.pop(field.attname, None)
        if field_mask is None and field_att_mask is None:
            select_mask.setdefault(field, {})
        elif field_mask:
            if not field.is_relation:
                raise FieldError(next(iter(field_mask)))
            field_select_mask = select_mask.setdefault(field, {})
            related_model = field.remote_field.model._meta.concrete_model
            self._get_defer_select_mask(
                related_model, field_mask, field_select_mask
            )

    for field_name, field_mask in mask.items():
        if filtered_relation := self._filtered_relations.get(field_name):
            relation = opts.get_field(filtered_relation.relation_name)
            field_select_mask = select_mask.setdefault((field_name, relation.field), {})
            related_model = relation.field.model._meta.concrete_model
            self._get_defer_select_mask(
                related_model, field_mask, field_select_mask
            )
        else:
            field = opts.get_field(field_name)
            if isinstance(field, models.ManyToManyField):
                for rel in field.remote_field.model._meta.related_objects:
                    field_select_mask = select_mask.setdefault((field_name, rel.field), {})
