                        related_model, field_mask, field_select_mask
                    )
            else:
                field_select_mask = select_mask.setdefault(field.field, {})
                related_model = field.field.model._meta.concrete_model
                self._get_defer_select_mask(
                    related_model, field_mask, field_select_mask
                )

